-- migration_027_new_questions_sept2026l.sql
-- Batch 12 of new questions from "questions to add.pdf" (Clinical Pain):
--   q_mtf_trigeminal_neuralgia_001 (MTF, Clinical Pain) -- new knowledge box "Trigeminal Neuralgia"
--     (incl. new images/trigeminal-nerve-divisions.svg) + relevantReading (2x BJA Ed, NICE CKS)
--   q_emq_headache_disorders_001 (EMQ, Clinical Pain) -- new knowledge box "Headache" in the
--     EMQ reference field (bare box) + relevantReading (3x BJA Education)
-- Retroactive: q_tn_facial_pain_001 -- the shared "Trigeminal Neuralgia" box appended
--   (byte-identical, so knowledge-summary.html dedupes it).
--
-- Author revisions applied: TN incidence 3-5/100,000, MVD hearing loss 1% and mortality ~0.5%
-- in all boxes; ICHD criterion B = "at least one of"; cluster O2 >=12 L/min non-rebreathe;
-- removed "paracetamol alone ineffective" and methysergide; migraine M:F ~1:3; MOH withdrawal
-- abrupt for simple analgesics/triptans, tapered for opioids.
--
-- New questions use ON CONFLICT DO UPDATE so this is correct whether or not an earlier draft
-- of this migration was already run. Idempotent; safe to re-run. No new categories.

-- ===== New questions =====
insert into questions (id, type, data, status) values ('q_mtf_trigeminal_neuralgia_001', 'MTF', '{"dateAdded":"2026-09-30","rotationIndex":130,"stem":"Trigeminal neuralgia:","choices":["Requires radiological imaging to establish the diagnosis","Has a peak onset in the fifth and sixth decades of life","Occurs in 20% of patients with multiple sclerosis","Is best treated with carbamazepine","When treated by microvascular decompression surgery, is associated with a 5% mortality"],"correct":[false,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Trigeminal neuralgia is a clinical diagnosis of brief, electric shock-like, unilateral facial pain in a trigeminal distribution. Imaging is used to look for secondary causes, carbamazepine is first-line, and microvascular decompression offers the most durable surgical relief at a low mortality.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; Trigeminal neuralgia is primarily a <strong>clinical diagnosis</strong>, based on the characteristic history of severe, paroxysmal, unilateral facial pain in a trigeminal distribution. MRI is recommended to <strong>exclude secondary causes</strong> (e.g. vascular compression, tumour, multiple sclerosis plaque) rather than being required to establish the diagnosis, and a normal scan does not exclude the diagnosis.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Trigeminal neuralgia typically has a <strong>peak onset in the fifth and sixth decades of life</strong>, with incidence increasing with age; younger-onset cases should raise suspicion of an underlying secondary cause such as multiple sclerosis.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Trigeminal neuralgia occurs in approximately <strong>2&ndash;5%</strong> of patients with multiple sclerosis (not 20%), reflecting demyelinating plaques affecting the trigeminal nerve root entry zone &mdash; considerably higher than the general population prevalence, but nowhere near 20%.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; <strong>Carbamazepine</strong> is the first-line and best-evidenced pharmacological treatment for trigeminal neuralgia, with a well-established licensed indication and the strongest supporting trial evidence among the anticonvulsants used for this condition.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Microvascular decompression is associated with a <strong>low mortality rate</strong>, generally cited as <strong>well under 1%</strong>, although it carries other recognised risks (hearing loss, facial numbness, CSF leak, stroke, and rarely death).</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Trigeminal Neuralgia</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A unilateral painful disorder characterised by <strong>brief, electric shock-like pains</strong>, abrupt in onset and termination, limited to the distribution of one or more divisions of the trigeminal nerve.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology</div><table style=\"margin:0\"><tr><th>Incidence / prevalence</th><td>Annual incidence 3&ndash;5/100,000; worldwide prevalence 10&ndash;300/100,000</td></tr><tr><th>Age</th><td><strong>Peak age of onset 50&ndash;60 years</strong>; rare under 40 years</td></tr><tr><th>Sex</th><td><strong>Male:female ratio 1:2</strong> &mdash; women affected almost twice as often</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Aetiology and Pathophysiology</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Exact mechanism unclear; the leading model is the <strong>&ldquo;ignition theory&rdquo;</strong> &mdash; abnormal hyperexcitability of afferent neurones in the trigeminal root/ganglion following injury</td></tr><tr><td>Most cases are attributed to <strong>demyelination at the root entry zone</strong>, where Schwann cell (peripheral) myelin meets astrocyte (central) myelin, near the pons</td></tr><tr><td><strong>Ephaptic cross-talk</strong>: demyelinated A&beta; (touch) fibres lying close to A&delta;/C (pain) fibres allow trivial tactile stimulation to trigger pain</td></tr><tr><td><strong>Vascular compression</strong> (typically by the <strong>superior cerebellar artery</strong>) is the most commonly implicated cause of demyelination, supported by surgical/MRI evidence &mdash; although vascular contact is an inconsistent finding and is also seen incidentally in people without TN</td></tr><tr><td><strong>Risk factors</strong>: multiple sclerosis, increasing age, stroke, hypertension (in women), Charcot-Marie-Tooth disease, tumours near the trigeminal root</td></tr><tr><td><strong>MS-associated TN</strong> presents at a <strong>younger age</strong> and tolerates anticonvulsants less well, but responds to interventions similarly to classical TN</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification</div><table style=\"margin:0\"><tr><th>Type</th><th>Definition</th><th>Subtypes</th></tr><tr><td><strong>Classical TN</strong></td><td>No apparent cause other than possible neurovascular compression</td><td><strong>Purely paroxysmal</strong> &mdash; pain-free between attacks<br><strong>With concomitant persistent facial pain</strong> (atypical TN / TN type 2) &mdash; low-grade background pain persists; central sensitisation implicated; neurovascular compression often not demonstrable; more treatment-resistant</td></tr><tr><td><strong>Idiopathic TN</strong></td><td>No apparent cause, with no neurovascular compression</td><td><strong>Purely paroxysmal</strong><br><strong>With concomitant persistent facial pain</strong></td></tr><tr><td><strong>Secondary TN</strong></td><td>Caused by an identifiable disorder &mdash; MS, herpes zoster, trauma, space-occupying lesion</td><td>&mdash;</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic Criteria (NICE CKS, Adapted from ICHD)</div><table style=\"margin:0\"><tr><th>A</th><td>Paroxysmal attacks lasting a fraction of a second to 2 minutes, in one or more trigeminal divisions, fulfilling B and C</td></tr><tr><th>B</th><td>Pain has at least one of: (1) intense, sharp, superficial or stabbing quality; (2) precipitated from trigger areas or by trigger factors</td></tr><tr><th>C</th><td>Attacks are stereotyped in the individual patient</td></tr><tr><th>D</th><td>No clinically evident neurological deficit</td></tr><tr><th>E</th><td>Not attributed to another disorder</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Red Flags Suggesting Secondary TN</div><table style=\"margin:0\"><tr><th>Red flag</th></tr><tr><td>Sensory deficit, absent trigeminal reflexes, bilateral involvement</td></tr><tr><td>Younger age of onset (&lt;40 years)</td></tr><tr><td>Pain that is persistent rather than paroxysmal</td></tr><tr><td>Difficult-to-control pain</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Differential Diagnosis</div><table style=\"margin:0\"><tr><th>Headache disorders</th><td>Cluster headache, other trigeminal autonomic cephalalgias</td></tr><tr><th>Dental pain</th><td>Cracked tooth, dental abscess</td></tr><tr><th>Joint</th><td>Temporomandibular joint disorder</td></tr><tr><th>Other neuralgias</th><td>Occipital, glossopharyngeal, post-herpetic neuralgia; atypical facial pain</td></tr><tr><th>Tumours</th><td>Acoustic neuroma, meningioma</td></tr><tr><th>Other</th><td>Sinusitis</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Investigations</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Primarily a <strong>clinical diagnosis</strong> &mdash; no investigation is required to confirm it</td></tr><tr><td><strong>MRI brain</strong> identifies a secondary cause in up to 15% of patients, and high-resolution MRI may identify vascular compression; recommended particularly where red flags are present, and NICE CKS advises specialist referral for MRI assessment in general</td></tr><tr><td>Neurological examination to detect deficit, trigger areas and laterality</td></tr><tr><td>Evoked potentials / quantitative sensory testing / electrophysiology &mdash; insufficient evidence for routine use</td></tr><tr><td>Pre-operative MR tomographic angiography may aid patient selection and outcome prediction for MVD</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Relevant Anatomy</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>CN V is the <strong>largest cranial nerve</strong> &mdash; mixed sensory and motor</td></tr><tr><td>The sensory root forms the <strong>trigeminal (Gasserian) ganglion</strong> within <strong>Meckel&rsquo;s cave</strong> (middle cranial fossa), dividing into V1 (ophthalmic), V2 (maxillary) and V3 (mandibular)</td></tr><tr><td>Exits: <strong>V1</strong> via the superior orbital fissure; <strong>V2</strong> via the foramen rotundum; <strong>V3</strong> via the foramen ovale</td></tr><tr><td>The motor root travels with the sensory root but distributes <strong>only via V3</strong>, supplying the muscles of mastication</td></tr><tr><td>Parasympathetic fibres are carried via trigeminal branches to the lacrimal gland (V1/V2), nasal glands (V2) and submandibular/sublingual/parotid glands (V3)</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/trigeminal-nerve-divisions.svg\" alt=\"The trigeminal nerve: sensory root from the pons to the Gasserian ganglion in Meckel&rsquo;s cave, dividing into V1 (superior orbital fissure), V2 (foramen rotundum) and V3 (foramen ovale), with the motor root joining V3, and the three levels targeted by surgery\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacological Management</div><table style=\"margin:0\"><tr><th>Drug</th><th>Role</th><th>Notes</th></tr><tr><td><strong>Carbamazepine</strong></td><td><strong>First-line</strong></td><td><strong>NNT 1.8</strong>; blocks use-dependent sodium channels and may prevent synaptic transmission in the trigeminal nucleus. Start 100 mg once or twice daily and titrate; usual dose 200 mg 3&ndash;4 times daily, max 1.6 g/day. Side effects: drowsiness, dizziness, rash, liver damage, hyponatraemia, ataxia &mdash; monitor LFTs, FBC and electrolytes</td></tr><tr><td><strong>Oxcarbazepine</strong></td><td>Alternative</td><td>Carbamazepine derivative; better side-effect profile, similar efficacy</td></tr><tr><td>Gabapentin, pregabalin, amitriptyline</td><td>Commonly used</td><td>Efficacy specific to TN not strongly evidenced (the NICE neuropathic pain pathway explicitly excludes TN)</td></tr><tr><td>Baclofen, lamotrigine</td><td>Add-on therapy</td><td>Baclofen may help in MS-associated TN</td></tr><tr><td>Phenytoin</td><td>Limited benefit</td><td>Used in some cases</td></tr><tr><td>Opioids</td><td>Not recommended</td><td>Ineffective for paroxysmal TN pain; NICE advises against starting them in non-specialist settings</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">If carbamazepine is ineffective, not tolerated or contraindicated &rarr; seek specialist advice / early referral, rather than cycling through other non-specific analgesics.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Surgical Management (Failed or Intolerant of Pharmacotherapy)</div><table style=\"margin:0\"><tr><th>Level</th><th>Procedure</th><th>Outcome</th><th>Risks</th></tr><tr><td><strong>Peripheral</strong></td><td>Branch neurolysis &mdash; laser, alcohol, neurectomy</td><td>Short-term relief (6 months&ndash;1 year); useful if unfit for other surgery, or as an emergency procedure</td><td>Dysaesthesia</td></tr><tr><td><strong>Gasserian ganglion</strong> (percutaneous, via foramen ovale under fluoroscopy)</td><td>Thermal (radiofrequency), chemical (glycerol/phenol/alcohol) or mechanical (balloon compression) ablation</td><td>Relief for ~4&ndash;5 years in 50% of patients</td><td>High incidence of sensory loss/dysaesthesia; ~4% develop <strong>anaesthesia dolorosa</strong>. Balloon compression specifically: arrhythmias, aseptic meningitis, temporary diplopia</td></tr><tr><td><strong>Posterior fossa</strong></td><td><strong>Microvascular decompression (MVD)</strong> &mdash; suboccipital craniotomy; the vessel (typically the superior cerebellar artery) is separated from the nerve root with Teflon felt</td><td><strong>Best initial success rate (80&ndash;90%)</strong> and the most sustained relief of all procedures; 10-year relapse ~30&ndash;40%</td><td>Mortality ~0.5% (major neurosurgery); aseptic meningitis (11%), hearing loss (1%), sensory loss (7%), CSF leak, haematoma, infarcts</td></tr><tr><td><strong>Posterior fossa</strong></td><td><strong>Gamma knife stereotactic radiosurgery</strong> &mdash; focused radiation to the nerve root where vascular compression is confirmed on MRI mapping</td><td>Complete relief in up to 69% by 1 year, but benefit may not be sustained; can be repeated; an option for patients unsuitable for MVD</td><td>Facial numbness, paraesthesia</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Psychological and Other Interventions</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Multidisciplinary input</strong>, including psychology, is valuable given the significant impact on wellbeing; CBT and ACT are considered, although the evidence quality is limited</td></tr><tr><td>Neuromodulation (trigeminal, occipital, peripheral nerve, spinal cord, motor cortex stimulation) &mdash; not yet robust enough for routine use</td></tr><tr><td>Non-invasive repetitive transcranial magnetic stimulation &mdash; benefit shown in orofacial pain generally; role in TN specifically not established</td></tr><tr><td>Botulinum toxin type A &mdash; case reports/open studies only; larger trials needed</td></tr><tr><td>TENS, acupuncture, 5% lidocaine patches &mdash; tried with varying results</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Trigeminal neuralgia","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30037-9/fulltext"},{"label":"Diagnosis and management of chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(20)30002-0/fulltext"},{"label":"Trigeminal neuralgia","source":"NICE CKS","url":"https://cks.nice.org.uk/topics/trigeminal-neuralgia/"}]}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;
insert into questions (id, type, data, status) values ('q_emq_headache_disorders_001', 'EMQ', '{"dateAdded":"2026-09-30","rotationIndex":131,"stem":"Headache disorders","lead":"For each scenario below, choose the single most appropriate answer from the list above. Each option may be used once, more than once, or not at all.","options":["Cerebral secondary malignancy","Cluster headache","Chronic daily headache","Migraine","Occipital headache","Secondary headache","Tension-type headache","Trigeminal neuralgia"],"questions":[{"question":"A 20-year-old student complains of generalised pain in the back of her head and neck that feels like a \"tight band\". Her headaches normally come on during the day and get worse as the day goes on.","correct":6,"explanation":"<strong>G. Tension-type headache</strong> &mdash; bilateral, band-like, pressing pain affecting the back of the head and neck, worsening as the day progresses, is the classic presentation of tension-type headache, the most common primary headache disorder."},{"question":"This headache is commonly associated with an aura.","correct":3,"explanation":"<strong>D. Migraine</strong> &mdash; migraine is the headache classically associated with aura: transient, fully reversible visual, sensory, speech or motor neurological symptoms preceding or accompanying the headache, occurring in the subtype &ldquo;migraine with aura&rdquo;."},{"question":"This headache is commonly unilateral.","correct":3,"explanation":"<strong>D. Migraine</strong> &mdash; migraine is classically unilateral, pulsating and of moderate&ndash;severe intensity, typically aggravated by routine physical activity and associated with nausea, photophobia and/or phonophobia. Cluster headache and trigeminal neuralgia are <em>strictly</em> unilateral; &ldquo;commonly&rdquo; points to migraine, which is unilateral in about 60% of cases."},{"question":"This headache causes attacks that occur over several weeks or months and then remit for several months or years.","correct":1,"explanation":"<strong>B. Cluster headache</strong> &mdash; characterised by clusters of frequent, severe, strictly unilateral attacks occurring over a period of weeks to months, followed by remission periods that can last months to years &mdash; a defining episodic pattern that distinguishes it from other primary headaches."},{"question":"This headache is the most common primary headache.","correct":6,"explanation":"<strong>G. Tension-type headache</strong> &mdash; the most common primary headache disorder in the general population, although migraine causes greater disability and healthcare-seeking because of its severity."}],"reference":"<div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Headache</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and Classification</div><table style=\"margin:0\"><tr><th>Prevalence</th><td>Headache is the most common medical complaint &mdash; lifetime prevalence 93% in men and 99% in women</td></tr><tr><th>Primary headache</th><td>Accounts for <strong>&gt;90%</strong> of complaints (migraine, tension-type headache, cluster headache, trigeminal autonomic cephalalgias)</td></tr><tr><th>Pain pathways</th><td>Head and neck pain is mediated via afferent fibres of the trigeminal, nervus intermedius, glossopharyngeal and vagus nerves, plus the upper cervical roots via the occipital nerves</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Primary Headaches at a Glance</div><table style=\"margin:0\"><tr><th>Feature</th><th>Migraine</th><th>Tension-type</th><th>Cluster</th></tr><tr><td><strong>Site</strong></td><td>Unilateral (60%) or bilateral (40%)</td><td>Bilateral, generalised, band-like</td><td><strong>Strictly unilateral</strong></td></tr><tr><td><strong>Character</strong></td><td>Throbbing/pulsating, moderate&ndash;severe</td><td>Pressing/tightening, mild&ndash;moderate</td><td>Extreme intensity</td></tr><tr><td><strong>Duration</strong></td><td>4&ndash;72 hours</td><td>30 minutes &ndash; 7 days</td><td>15&ndash;180 minutes</td></tr><tr><td><strong>Physical activity</strong></td><td>Aggravates</td><td>Unaffected</td><td>Agitation / restlessness</td></tr><tr><td><strong>Associated features</strong></td><td>Nausea, photophobia, phonophobia; aura in 30%</td><td>Nausea/photophobia/phonophobia not prominent</td><td>Ipsilateral autonomic features; Horner&rsquo;s in ~20%</td></tr><tr><td><strong>Pattern</strong></td><td>Recurrent attacks</td><td>Episodic or chronic</td><td>Clusters over weeks&ndash;months, remission for months&ndash;years</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications for Neuroimaging</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Sudden-onset headache</td></tr><tr><td>History suggestive of focal neurological dysfunction</td></tr><tr><td>Headache with fever / weight loss</td></tr><tr><td>Previous malignancy</td></tr><tr><td>Previous chronic infection (including HIV)</td></tr><tr><td>Neurological abnormality on examination</td></tr><tr><td>Course not matching the presumed diagnosis</td></tr><tr><td>Repeated attendance with the same symptoms</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Migraine</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><th>Types</th><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><th>Aura</th><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><th>Headache</th><td>Unilateral (60%) or bilateral (40%), lasting <strong>4&ndash;72 hours</strong>, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><th>Aggravating factors</th><td>Postural change, activity, raised ICP</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Migraine treatment</p><table style=\"margin:0\"><tr><th>Stress</th><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><th>Depression / anxiety</th><td>Specific therapy</td></tr><tr><th>Menstrual migraine</th><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><th>Acute &mdash; stepped management</th><td><strong>1.</strong> Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br><strong>2.</strong> Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br><strong>3.</strong> CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><th>Prophylaxis</th><td><strong>1st line:</strong> &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br><strong>2nd line:</strong> topiramate, sodium valproate<br><strong>3rd line:</strong> CGRP monoclonal antibodies</td></tr><tr><th>Non-drug</th><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tension-Type Headache (TTH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Most common primary headache disorder</strong>; lifetime prevalence 69% (men), 88% (women)</td></tr><tr><td>Subdivided into episodic (ETTH &mdash; frequent/infrequent) and chronic (CTTH)</td></tr><tr><td>Generalised pressure/tightness, mild&ndash;moderate, <strong>unaffected by activity</strong>; nausea/photophobia/phonophobia not prominent</td></tr><tr><td>Infrequent ETTH (&lt;1/month): minimal impact, responds to simple analgesics</td></tr><tr><td>Frequent ETTH and CTTH: considerable disability</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cluster Headache and Trigeminal Autonomic Cephalalgias</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td><strong>Male:female ratio 9:1</strong>; prevalence 0.1&ndash;0.4%; onset typically 20&ndash;40 years</td></tr><tr><th>Pattern</th><td>Attacks occur over <strong>weeks&ndash;months</strong>, then remit for months&ndash;years</td></tr><tr><th>Features</th><td>Extreme pain intensity &rarr; agitation/restlessness; nausea/vomiting uncommon (unlike migraine); ipsilateral Horner&rsquo;s syndrome in ~20%</td></tr><tr><th>Triggers (cluster phase only)</th><td>Alcohol, vasodilators, sleep apnoea-induced hypoxaemia</td></tr><tr><th>Prophylaxis</th><td><strong>Verapamil</strong> (up to 960 mg/day), ergotamine (short-term episodic use), lithium (tolerance can develop), prednisolone (60&ndash;100 mg for 2&ndash;5 days); gabapentin/valproate &mdash; limited evidence</td></tr><tr><th>Acute</th><td>Sumatriptan (intranasal/SC), zolmitriptan, <strong>100% oxygen at &ge;12 L/min</strong> via a non-rebreathe mask for 10&ndash;20 min (effective, particularly in younger patients); intranasal lidocaine in a subgroup; occipital nerve stimulation &mdash; emerging, insufficient evidence</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Other trigeminal autonomic cephalalgias</p><table style=\"margin:0\"><tr><th>Feature</th><th>Paroxysmal hemicrania (PH)</th><th>SUNCT</th></tr><tr><td>Attack duration</td><td>8&ndash;25 minutes</td><td>20&ndash;120 seconds</td></tr><tr><td>Frequency</td><td>5&ndash;24/day</td><td>30&ndash;100/day, mostly daytime</td></tr><tr><td>Sex</td><td>Female predominance (1:3)</td><td>&mdash;</td></tr><tr><td>Key feature</td><td>Resembles cluster headache but fails standard anti-cluster therapy</td><td>Prominent autonomic hyperactivity, especially conjunctival tearing/injection; commonly misdiagnosed as trigeminal neuralgia</td></tr><tr><td>Treatment</td><td><strong>Absolute response to indomethacin</strong> (diagnostic and therapeutic)</td><td>Prevention: topiramate, valproate, gabapentin, lamotrigine (attacks too short to treat acutely)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Daily Headache (CDH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Not in ICHD-II R1; prevalence 3&ndash;5%</td></tr><tr><td>Defined as headache on <strong>&gt;15 days/month for &gt;3 months</strong></td></tr><tr><td>Four categories: <strong>transformed migraine</strong> (largest group, 70&ndash;80%), chronic tension-type headache, new daily persistent headache (NDPH), hemicrania continua</td></tr><tr><td>Transformed migraine: periodic migraine &ldquo;transforming&rdquo; to more frequent/continuous headache over years; treated as regular migraine</td></tr><tr><td>Hemicrania continua: rare, unremitting, unilateral; autonomic features (rhinorrhoea, conjunctival injection); responds to indomethacin</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Medication-overuse headache</p><table style=\"margin:0\"><tr><th>Provoking agents</th><td>Ergotamine, triptans, simple analgesics, opioids, combination analgesics</td></tr><tr><th>Prevalence</th><td>Present in up to 40% of chronic migraineurs</td></tr><tr><th>Management</th><td>Education, explanation and follow-up; <strong>abrupt withdrawal</strong> of simple analgesics and triptans, but <strong>gradual tapering</strong> of opioids</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Facial Pain</div><p style=\"margin:0 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Temporomandibular disorder (TMD)</p><table style=\"margin:0\"><tr><th>Definition</th><td>Generic term for muscle/joint conditions causing symptoms in the TMJ area; prevalence 30&ndash;46% (pain in 5&ndash;15%)</td></tr><tr><th>Investigations</th><td>Joint MRI, bone scintigraphy</td></tr><tr><th>Management</th><td>Self-care programme (jaw relaxation, softer diet, chewing technique, NSAIDs; avoid teeth grinding, prolonged opening, prone sleeping and caffeine), intra-oral splinting, analgesia, physiotherapy, TCAs for chronic pain, CBT techniques</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Trigeminal neuralgia</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 3&ndash;5/100,000; peak onset in the 5th&ndash;6th decade</td></tr><tr><th>Aetiology</th><td>~80% associated with vascular compression; diagnosed in up to 5% of MS patients</td></tr><tr><th>Drug treatment</th><td>First-line <strong>carbamazepine (NNT 1.8)</strong>; others: baclofen, gabapentin, lamotrigine, oxcarbazepine, topiramate; ~70% initially controlled non-surgically</td></tr><tr><th>MVD</th><td>90% short-term relief, 55&ndash;70% long-term; annual recurrence 3.5%; mortality ~0.5%; hearing loss 1%</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Post-herpetic neuralgia (PHN)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Acute zoster incidence 400/100,000/year; PHN occurs in 15% of acute zoster cases</td></tr><tr><th>Definition</th><td>Pain persisting in the affected dermatome at 3 months</td></tr><tr><th>Features</th><td>Typically affects the V1 division; trophic changes (scarring, depigmentation, hair loss), allodynia; most resolve within the first year</td></tr><tr><th>Treatment</th><td><strong>Amitriptyline</strong> is the agent of choice (early treatment shortens duration/severity); gabapentin useful if insomnia; capsaicin cream, topical lidocaine and opioids also used</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Persistent idiopathic facial pain (formerly atypical facial pain)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 1/100,000; equal sex incidence, but more women seek care</td></tr><tr><th>Associations</th><td>Strong association with functional disorders (IBS) and psychological distress</td></tr><tr><th>Features</th><td>Continuous dull ache with intermittent severe episodes, poorly localised, sparing the joints/muscles of mastication; no sensory loss or physical signs; investigations normal</td></tr><tr><th>Treatment</th><td>Primary analgesics ineffective; poor response to diagnostic nerve block; TCA analgesic response is independent of the antidepressant effect; long-term support often needed</td></tr></table></div></div>\n</div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do update set data = excluded.data;

